-- 1. Fréquence « Personnalisée » retirée : les règles ainsi configurées sont supprimées (l'historique de leurs envois est conservé).
DELETE FROM "NotificationRule" WHERE "frequency" = 'CUSTOM';
UPDATE "NotificationRule" SET "everyDays" = NULL WHERE "everyDays" IS NOT NULL;

