-- 2b. Tout autre texte : retrait automatique de la variable (et des guillemets ou de la ponctuation laissés orphelins).
CREATE OR REPLACE FUNCTION pg_temp.sans_variables_retirees(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT btrim(regexp_replace(regexp_replace(regexp_replace(regexp_replace(
    regexp_replace(t, '[[:space:]  ]*«[[:space:]  ]*\{(jalon|risque|seuil|document)\}[[:space:]  ]*»', '', 'g'),
    '[[:space:]  ]*\{(jalon|risque|seuil|document)\}', '', 'g'),
    '[[:space:]  ]+:[[:space:]]*([.,])', '\1', 'g'),
    '[[:space:]  ]*[·:,][[:space:]  ]*$', '', 'g'),
    '[[:space:]]{2,}', ' ', 'g'))
$$;
UPDATE "NotificationRule" SET
  "subject" = pg_temp.sans_variables_retirees("subject"),
  "body" = pg_temp.sans_variables_retirees("body"),
  "prompt" = pg_temp.sans_variables_retirees("prompt")
WHERE "subject" ~ '\{(jalon|risque|seuil|document)\}' OR "body" ~ '\{(jalon|risque|seuil|document)\}' OR "prompt" ~ '\{(jalon|risque|seuil|document)\}';

-- 3. Heures d'envoi alignées sur le pas de 30 minutes.
UPDATE "NotificationRule" SET "hour" = substr("hour", 1, 3) || CASE WHEN substr("hour", 4, 2)::int < 30 THEN '00' ELSE '30' END
WHERE "hour" ~ '^[0-2][0-9]:[0-5][0-9]$' AND substr("hour", 4, 2) NOT IN ('00', '30');
